#include <QCoreApplication>
#include <QFile>
#include <QImage>
#include <jxl/decode.h>
#include <jxl/thread_parallel_runner.h>
#include <vector>
#include <memory>
int main(int argc,char** argv){QCoreApplication app(argc,argv);if(app.arguments().size()!=3)return 2;QFile input(app.arguments()[1]);if(!input.open(QIODevice::ReadOnly)||input.size()>512ll*1024*1024)return 3;auto bytes=input.readAll();std::unique_ptr<JxlDecoder,decltype(&JxlDecoderDestroy)> decoder(JxlDecoderCreate(nullptr),JxlDecoderDestroy);std::unique_ptr<void,decltype(&JxlThreadParallelRunnerDestroy)> runner(JxlThreadParallelRunnerCreate(nullptr,2),JxlThreadParallelRunnerDestroy);if(!decoder||!runner)return 4;if(JxlDecoderSetParallelRunner(decoder.get(),JxlThreadParallelRunner,runner.get())!=JXL_DEC_SUCCESS)return 5;JxlDecoderSubscribeEvents(decoder.get(),JXL_DEC_BASIC_INFO|JXL_DEC_FULL_IMAGE);JxlDecoderSetInput(decoder.get(),reinterpret_cast<const uint8_t*>(bytes.constData()),size_t(bytes.size()));JxlBasicInfo info{};JxlPixelFormat format{4,JXL_TYPE_UINT8,JXL_NATIVE_ENDIAN,0};std::vector<uint8_t> pixels;for(;;){auto status=JxlDecoderProcessInput(decoder.get());if(status==JXL_DEC_BASIC_INFO){if(JxlDecoderGetBasicInfo(decoder.get(),&info)!=JXL_DEC_SUCCESS||!info.xsize||!info.ysize||info.xsize>16384||info.ysize>16384||uint64_t(info.xsize)*info.ysize>32000000)return 6;}else if(status==JXL_DEC_NEED_IMAGE_OUT_BUFFER){size_t size=0;if(JxlDecoderImageOutBufferSize(decoder.get(),&format,&size)!=JXL_DEC_SUCCESS||size>128000000)return 7;pixels.resize(size);if(JxlDecoderSetImageOutBuffer(decoder.get(),&format,pixels.data(),size)!=JXL_DEC_SUCCESS)return 8;}else if(status==JXL_DEC_FULL_IMAGE){QImage image(pixels.data(),int(info.xsize),int(info.ysize),int(info.xsize)*4,QImage::Format_RGBA8888);return image.save(app.arguments()[2],"PNG")?0:9;}else if(status==JXL_DEC_ERROR||status==JXL_DEC_NEED_MORE_INPUT||status==JXL_DEC_SUCCESS)return 10;}}
